Deno.test({
  name: "synthetics model: get_api_multistep_subtests surfaces API errors",
  // sanitizeResources: false — Deno.serve() listener outlives test scope
  sanitizeResources: false,
  fn: async () => {
    const { url, server } = startMockDdServer({
      "/subtests/test-id-123": {
        body: { errors: [{ status: "500", title: "Internal Error" }] },
        status: 500,
      },
    });
    const uninstall = installFetchMock(url);

    try {
      const { context } = createModelTestContext({
        globalArgs: {
          "apiKey": "test-api-key",
          "appKey": "test-app-key",
          "site": "us1",
        },
        definition: {
          id: "test-id",
          name: "test-synthetics",
          version: 1,
          tags: {},
        },
      });

      let threw = false;
      try {
        await (model.methods as Record<
          string,
          {
            execute: (
              args: Record<string, unknown>,
              ctx: unknown,
            ) => Promise<{ dataHandles: unknown[] }>;
          }
        >).get_api_multistep_subtests.execute(
          { "public_id": "test-id-123" },
          context,
        );
      } catch (_err) {
        threw = true;
      }
      assertEquals(threw, true);
    } finally {
      uninstall();
      await server.shutdown();
    }
  },
});
